library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# Load all data files
wave_one <- read_delim('data/input/wave_one_lsype_young_person_2020.tab', delim = '\t')
wave_two <- read_delim('data/input/wave_two_lsype_young_person_2020.tab', delim = '\t')
wave_three <- read_delim('data/input/wave_three_lsype_young_person_2020.tab', delim = '\t')
wave_four <- read_delim('data/input/wave_four_lsype_young_person_2020.tab', delim = '\t')
wave_six <- read_delim('data/input/wave_six_lsype_young_person_2020.tab', delim = '\t')
wave_seven <- read_delim('data/input/wave_seven_lsype_young_person_2020.tab', delim = '\t')
wave_eight <- read_delim('data/input/ns8_2015_self_completion.tab', delim = '\t')
wave_nine <- read_delim('data/input/ns9_2022_main_interview.tab', delim = '\t')

# Create wide data frame with all sweeps
# Add age column
data_long <- list(
  list(age = 14, nsid = wave_one$NSID, alcever = wave_one$W1alceverYP, alcmon = wave_one$W1alcmonYP),
  list(age = 15, nsid = wave_two$NSID, alcever = wave_two$W2alceverYP),
  list(age = 16, nsid = wave_three$NSID, alcever = wave_three$W3alceverYP),
  list(age = 17, nsid = wave_four$NSID, alcever = wave_four$W4AlcEverYP),
  list(age = 19, nsid = wave_six$NSID, alcever = wave_six$W6AlcEverYP),
  list(age = 20, nsid = wave_seven$NSID, alcever = wave_seven$W7AlcEverYP),
  list(age = 25, nsid = wave_eight$NSID, audit = wave_eight$W8AUDIT1),
  list(age = 32, nsid = wave_nine$NSID, audit = wave_nine$W9AUDIT1)
)

data_df <- bind_rows(data_long)

# Function to determine if drinking occurred at an age
check_drinking <- function(row, age) {
  if (age == 14) {
    # Special rule for sweep 1: need both W1alceverYP = 1 AND W1alcmonYP = 1
    alcever <- row[['alcever']]
    alcmon <- row[['alcmon']]

    # Check for missing values (user_missing_values are -999 to -1)
    alcever_is_missing <- is.na(alcever) || alcever <= -1
    alcmon_is_missing <- is.na(alcmon) || alcmon <= -1

    # Drinking if both are yes (1)
    drinking <- (alcever == 1 && alcmon == 1) && !alcever_is_missing && !alcmon_is_missing
  } else if (age >= 25) {
    # Sweep 8-9: AUDIT frequency above "Never" (code 1)
    # Values 2, 3, 4, 5 indicate drinking
    audit <- row[['audit']]

    audit_is_missing <- is.na(audit) || audit <= -1
    drinking <- (audit >= 2) && !audit_is_missing
  } else {
    # Sweeps 2-7: alcever = 1 indicates drinking
    alcever <- row[['alcever']]
    alcever_is_missing <- is.na(alcever) || alcever <= -1
    drinking <- (alcever == 1) && !alcever_is_missing
  }

  return(drinking)
}

# Define missing codes for each age
missing_codes <- c(-99, -97, -96, -92, -91, -1)

# Create a function to determine drinking status with proper missing handling
is_drinking <- function(age, var_name) {
  if (age == 14) {
    # Special rule for sweep 1
    return(function(row) {
      alcever <- row[['alcever']]
      alcmon <- row[['alcmon']]
      alcever_missing <- is.na(alcever) || alcever %in% missing_codes
      alcmon_missing <- is.na(alcmon) || alcmon %in% missing_codes

      # Drinking if both are yes (1) and neither is missing
      drinking <- (alcever == 1 && alcmon == 1) && !alcever_missing && !alcmon_missing
      return(drinking)
    })
  } else if (age >= 25) {
    # Sweep 8-9: AUDIT frequency above "Never" (code 1)
    return(function(row) {
      audit <- row[['audit']]
      audit_missing <- is.na(audit) || audit %in% missing_codes

      # Drinking if audit >= 2 and not missing
      drinking <- (audit >= 2) && !audit_missing
      return(drinking)
    })
  } else {
    # Sweeps 2-7: alcever = 1 indicates drinking
    return(function(row) {
      alcever <- row[['alcever']]
      alcever_missing <- is.na(alcever) || alcever %in% missing_codes

      # Drinking if alcever == 1 and not missing
      drinking <- (alcever == 1) && !alcever_missing
      return(drinking)
    })
  }
}

# Function to check if a value is missing
is_value_missing <- function(x, missing_codes) {
  is.na(x) || x %in% missing_codes
}

# Apply drinking checks to each row
apply_drinking <- function(row, age, var_name) {
  check_fn <- is_drinking(age, var_name)
  drinking <- check_fn(row)
  return(drinking)
}

# Create logic for each age
create_drinking_indicator <- function(age) {
  if (age == 14) {
    return(function(row) {
      alcever <- row[['alcever']]
      alcmon <- row[['alcmon']]
      alcever_missing <- is_value_missing(alcever, c(-99, -97, -96, -92, -91, -1))
      alcmon_missing <- is_value_missing(alcmon, c(-99, -97, -96, -92, -91, -1))

      drinking <- (alcever == 1 && alcmon == 1) && !alcever_missing && !alcmon_missing
      return(drinking)
    })
  } else if (age >= 25) {
    return(function(row) {
      audit <- row[['audit']]
      audit_missing <- is_value_missing(audit, c(-9, -8, -3, -1))

      drinking <- (audit >= 2) && !audit_missing
      return(drinking)
    })
  } else {
    return(function(row) {
      alcever <- row[['alcever']]
      alcever_missing <- is_value_missing(alcever, c(-99, -97, -96, -92, -91, -1))

      drinking <- (alcever == 1) && !alcever_missing
      return(drinking)
    })
  }
}

# Define ages in order
ages <- c(14, 15, 16, 17, 19, 20, 25, 32)

# Apply drinking checks
for (i in seq_along(ages)) {
  age <- ages[i]

  if (age == 14) {
    check_fn <- create_drinking_indicator(14)
  } else if (age >= 25) {
    check_fn <- create_drinking_indicator(25)
  } else {
    check_fn <- create_drinking_indicator(age)
  }

  data_df[[paste0('drinking_', i)]] <- mapply(check_fn, data_df, MoreArgs = list(age = age), SIMPLIFY = FALSE)
}

# Now find the earliest age where drinking occurred
# Initialize alcfst to 99 (never)
data_df$alcfst <- 99

# Track if any drinking was observed
data_df$drinking_observed <- FALSE

# Process each age in order
for (i in seq_along(ages)) {
  age <- ages[i]
  drinking_col <- paste0('drinking_', i)

  # For waves 8-9 (ages 25, 32), the variable name is audit
  if (age >= 25) {
    check_fn <- create_drinking_indicator(25)
    data_df[[drinking_col]] <- mapply(check_fn, data_df, MoreArgs = list(age = age), SIMPLIFY = FALSE)
  } else if (age == 14) {
    check_fn <- create_drinking_indicator(14)
    data_df[[drinking_col]] <- mapply(check_fn, data_df, MoreArgs = list(age = age), SIMPLIFY = FALSE)
  } else {
    check_fn <- create_drinking_indicator(age)
    data_df[[drinking_col]] <- mapply(check_fn, data_df, MoreArgs = list(age = age), SIMPLIFY = FALSE)
  }

  # Update alcfst for those who drank at this age
  drinking_data <- data_df[[drinking_col]] == TRUE
  if (any(drinking_data)) {
    data_df[drinking_data, 'alcfst'] <- age
    data_df[drinking_data, 'drinking_observed'] <- TRUE
  }
}

# For those who didn't drink at any observed wave but at least one indicator is missing,
# assign -8 (don't know / insufficient information)
# This means: no drinking observed, but at least one indicator is missing

# First, identify all missing indicator values
is_missing_14 <- function(row) {
  alcever <- row[['alcever']]
  alcmon <- row[['alcmon']]
  is.na(alcever) || alcever %in% c(-99, -97, -96, -92, -91, -1) ||
  is.na(alcmon) || alcmon %in% c(-99, -97, -96, -92, -91, -1)
}

is_missing_15 <- function(row) {
  alcever <- row[['alcever']]
  is.na(alcever) || alcever %in% c(-99, -97, -96, -92, -91, -1)
}

is_missing_16 <- function(row) {
  alcever <- row[['alcever']]
  is.na(alcever) || alcever %in% c(-99, -97, -96, -92, -91, -1)
}

is_missing_17 <- function(row) {
  alcever <- row[['alcever']]
  is.na(alcever) || alcever %in% c(-99, -97, -96, -92, -91, -1)
}

is_missing_19 <- function(row) {
  alcever <- row[['alcever']]
  is.na(alcever) || alcever %in% c(-99, -97, -96, -92, -91, -1)
}

is_missing_20 <- function(row) {
  alcever <- row[['alcever']]
  is.na(alcever) || alcever %in% c(-99, -97, -96, -92, -91, -1)
}

is_missing_25 <- function(row) {
  audit <- row[['audit']]
  is.na(audit) || audit %in% c(-9, -8, -3, -1)
}

is_missing_32 <- function(row) {
  audit <- row[['audit']]
  is.na(audit) || audit %in% c(-9, -8, -3, -1)
}

# Count missing indicators per person
missing_14 <- sapply(data_df, is_missing_14)
missing_15 <- sapply(data_df, is_missing_15)
missing_16 <- sapply(data_df, is_missing_16)
missing_17 <- sapply(data_df, is_missing_17)
missing_19 <- sapply(data_df, is_missing_19)
missing_20 <- sapply(data_df, is_missing_20)
missing_25 <- sapply(data_df, is_missing_25)
missing_32 <- sapply(data_df, is_missing_32)

# Combine all missing indicators
any_missing <- missing_14 | missing_15 | missing_16 | missing_17 | missing_19 | missing_20 | missing_25 | missing_32

# Update alcfst where drinking_observed is FALSE but any_missing is TRUE
data_df$alcfst <- ifelse(data_df$drinking_observed & data_df$alcfst != 99, data_df$alcfst, ifelse(any_missing, -8, 99))

# Create factor with correct levels and labels
alcfst_factor <- factor(data_df$alcfst, 
                        levels = c(14, 15, 16, 17, 19, 20, 25, 32, 99, -8),
                        labels = c('Age 14', 'Age 15', 'Age 16', 'Age 17', 'Age 19', 'Age 20', 'Age 25', 'Age 32', 'Never had alcohol', 'Don\'t know/insufficient information'))

# Keep only NSID and alcfst
data_df <- data_df[, c('NSID', 'alcfst')]

# Write output
write_csv(data_df, 'data/output/cleaned_data.csv')

