wave_seven <- read_delim('data/input/wave_seven_lsype_young_person_2020.tab', delim = '\t')
wave_eight <- read_delim('data/input/ns8_2015_self_completion.tab', delim = '\t')
wave_nine <- read_delim('data/input/ns9_2022_main_interview.tab', delim = '\t')

# Define the columns we need from each file
# S1 (age 14): W1alceverYP, W1alcmonYP
# S2 (age 15): W2alceverYP
# S3 (age 16): W3alceverYP
# S4 (age 17): W4AlcEverYP
# S6 (age 19): W6AlcEverYP
# S7 (age 20): W7AlcEverYP
# S8 (age 25): W8AUDIT1
# S9 (age 32): W9AUDIT1

# Function to check if value is missing
is_missing <- function(x, codes) {
  is.na(x) || x %in% codes
}

# Function to check drinking at each age
check_drinking_s1 <- function(row) {
  alcever <- row[['W1alceverYP']]
  alcmon <- row[['W1alcmonYP']]
  # Both must be 1 (Yes), and neither missing
  drinking <- (alcever == 1 && alcmon == 1) && !is_missing(alcever, c(-99, -97, -96, -92, -91, -1)) && !is_missing(alcmon, c(-99, -97, -96, -92, -91, -1))
  return(drinking)
}

check_drinking_s2 <- function(row) {
  alcever <- row[['W2alceverYP']]
  drinking <- (alcever == 1) && !is_missing(alcever, c(-998, -997, -995, -99, -97, -96, -92, -91, -1))
  return(drinking)
}

check_drinking_s3 <- function(row) {
  alcever <- row[['W3alceverYP']]
  drinking <- (alcever == 1) && !is_missing(alcever, c(-99, -97, -96, -92, -91, -1))
  return(drinking)
}

check_drinking_s4 <- function(row) {
  alcever <- row[['W4AlcEverYP']]
  drinking <- (alcever == 1) && !is_missing(alcever, c(-99, -97, -96, -92, -91, -1))
  return(drinking)
}

check_drinking_s6 <- function(row) {
  alcever <- row[['W6AlcEverYP']]
  drinking <- (alcever == 1) && !is_missing(alcever, c(-997, -97, -92, -91, -1))
  return(drinking)
}

check_drinking_s7 <- function(row) {
  alcever <- row[['W7AlcEverYP']]
  drinking <- (alcever == 1) && !is_missing(alcever, c(-996, -97, -92, -91, -1))
  return(drinking)
}

check_drinking_s8 <- function(row) {
  audit <- row[['W8AUDIT1']]
  # AUDIT: code 1 = Never, codes 2+ indicate drinking
  drinking <- (audit >= 2) && !is_missing(audit, c(-9, -8, -3, -1))
  return(drinking)
}

check_drinking_s9 <- function(row) {
  audit <- row[['W9AUDIT1']]
  # AUDIT: code 1 = Never, codes 2+ indicate drinking
  drinking <- (audit >= 2) && !is_missing(audit, c(-9, -8, -3, -1))
  return(drinking)
}

# Create a data frame with NSID and drinking status for each age
all_ages <- data.frame(
  NSID = character(),
  age_drinking = logical(),
  age = integer(),
  stringsAsFactors = FALSE
)

# Add each age's drinking status
# S1 (age 14)
all_ages <- rbind(all_ages, data.frame(
  NSID = wave_one$NSID,
  age_drinking = mapply(check_drinking_s1, wave_one),
  age = 14,
  stringsAsFactors = FALSE
))

# S2 (age 15)
all_ages <- rbind(all_ages, data.frame(
  NSID = wave_two$NSID,
  age_drinking = mapply(check_drinking_s2, wave_two),
  age = 15,
  stringsAsFactors = FALSE
))

# S3 (age 16)
all_ages <- rbind(all_ages, data.frame(
  NSID = wave_three$NSID,
  age_drinking = mapply(check_drinking_s3, wave_three),
