  NSID = wave_four$NSID,
  age_drinking = mapply(check_drinking_s4, wave_four),
  age = 17,
  stringsAsFactors = FALSE
))

# S6 (age 19)
all_ages <- rbind(all_ages, data.frame(
  NSID = wave_six$NSID,
  age_drinking = mapply(check_drinking_s6, wave_six),
  age = 19,
  stringsAsFactors = FALSE
))

# S7 (age 20)
all_ages <- rbind(all_ages, data.frame(
  NSID = wave_seven$NSID,
  age_drinking = mapply(check_drinking_s7, wave_seven),
  age = 20,
  stringsAsFactors = FALSE
))

# S8 (age 25)
all_ages <- rbind(all_ages, data.frame(
  NSID = wave_eight$NSID,
  age_drinking = mapply(check_drinking_s8, wave_eight),
  age = 25,
  stringsAsFactors = FALSE
))

# S9 (age 32)
all_ages <- rbind(all_ages, data.frame(
  NSID = wave_nine$NSID,
  age_drinking = mapply(check_drinking_s9, wave_nine),
  age = 32,
  stringsAsFactors = FALSE
))

# Reshape to wide format: one row per NSID, columns for each age's drinking status
long_df <- all_ages %>%
  select(NSID, age, age_drinking) %>%
  pivot_wider(names_from = age, values_from = age_drinking, names_prefix = 'drinking_') %>%
  arrange(NSID)

# Now determine alcfst for each person
# Sort ages: 14, 15, 16, 17, 19, 20, 25, 32
ages <- c(14, 15, 16, 17, 19, 20, 25, 32)

# Find earliest age with drinking = TRUE
# Also track if any indicator is missing (for -8 case)

# First, check for missing indicators at each age
check_missing_s1 <- function(row) {
  alcever <- row[['W1alceverYP']]
  alcmon <- row[['W1alcmonYP']]
  is_missing(alcever, c(-99, -97, -96, -92, -91, -1)) || is_missing(alcmon, c(-99, -97, -96, -92, -91, -1))
}

check_missing_s2 <- function(row) {
  alcever <- row[['W2alceverYP']]
  is_missing(alcever, c(-998, -997, -995, -99, -97, -96, -92, -91, -1))
}

check_missing_s3 <- function(row) {
  alcever <- row[['W3alceverYP']]
  is_missing(alcever, c(-99, -97, -96, -92, -91, -1))
}

check_missing_s4 <- function(row) {
  alcever <- row[['W4AlcEverYP']]
  is_missing(alcever, c(-99, -97, -96, -92, -91, -1))
}

check_missing_s6 <- function(row) {
  alcever <- row[['W6AlcEverYP']]
  is_missing(alcever, c(-997, -97, -92, -91, -1))
}

check_missing_s7 <- function(row) {
  alcever <- row[['W7AlcEverYP']]
  is_missing(alcever, c(-996, -97, -92, -91, -1))
}

check_missing_s8 <- function(row) {
  audit <- row[['W8AUDIT1']]
  is_missing(audit, c(-9, -8, -3, -1))
}

check_missing_s9 <- function(row) {
  audit <- row[['W9AUDIT1']]
  is_missing(audit, c(-9, -8, -3, -1))
}

# Create a list of all data to merge
merge_data <- list(
  list(wave_one, c('NSID', 'W1alceverYP', 'W1alcmonYP'), check_missing_s1, 14),
  list(wave_two, c('NSID', 'W2alceverYP'), check_missing_s2, 15),
  list(wave_three, c('NSID', 'W3alceverYP'), check_missing_s3, 16),
  list(wave_four, c('NSID', 'W4AlcEverYP'), check_missing_s4, 17),
  list(wave_six, c('NSID', 'W6AlcEverYP'), check_missing_s6, 19),
  list(wave_seven, c('NSID', 'W7AlcEverYP'), check_missing_s7, 20),
  list(wave_eight, c('NSID', 'W8AUDIT1'), check_missing_s8, 25),
  list(wave_nine, c('NSID', 'W9AUDIT1'), check_missing_s9, 32)
)

# Get full cohort frame from wave_one
cohort <- wave_one[, c('NSID')]

# Create result data frame
result <- cohort

# For each age, find those who drank and those with missing
for (merge_info in merge_data) {
  wave_data <- merge_info[[1]]
  cols <- merge_info[[2]]
  missing_check <- merge_info[[3]]
  age <- merge_info[[4]]

  # Check drinking status
  apply_drinking <- FALSE
  apply_missing <- FALSE

  if (age == 14) {
    apply_drinking <- mapply(check_drinking_s1, wave_data)
    apply_missing <- mapply(check_missing_s1, wave_data)
  } else if (age == 15) {
    apply_drinking <- mapply(check_drinking_s2, wave_data)
    apply_missing <- mapply(check_missing_s2, wave_data)
  } else if (age == 16) {
    apply_drinking <- mapply(check_drinking_s3, wave_data)
    apply_missing <- mapply(check_missing_s3, wave_data)
  } else if (age == 17) {
    apply_drinking <- mapply(check_drinking_s4, wave_data)
    apply_missing <- mapply(check_missing_s4, wave_data)
  } else if (age == 19) {
    apply_drinking <- mapply(check_drinking_s6, wave_data)
    apply_missing <- mapply(check_missing_s6, wave_data)
  } else if (age == 20) {
    apply_drinking <- mapply(check_drinking_s7, wave_data)
    apply_missing <- mapply(check_missing_s7, wave_data)
  } else if (age == 25) {
    apply_drinking <- mapply(check_drinking_s8, wave_data)
    apply_missing <- mapply(check_missing_s8, wave_data)
  } else if (age == 32) {
    apply_drinking <- mapply(check_drinking_s9, wave_data)
    apply_missing <- mapply(check_missing_s9, wave_data)
  }

  # Find rows where this age has drinking
  drinking_at_age <- (apply_drinking == TRUE)

  # Update alcfst for those who drank at this age (earliest wins)
  result$alcfst <- ifelse(drinking_at_age & is.na(result$alcfst), age, result$alcfst)

  # Track if drinking is ever observed
  result$drinking_observed <- result$drinking_observed | drinking_at_age
}

# Initialize alcfst to 99 (never) for all
result$alcfst <- ifelse(is.na(result$alcfst), 99, result$alcfst)

# Now handle the -8 case: no drinking observed but at least one indicator is missing
# We need to check if any indicator is missing across all ages

# Create a full indicator status for each person
any_missing <- FALSE
for (merge_info in merge_data) {
  wave_data <- merge_info[[1]]
  cols <- merge_info[[2]]
  missing_check <- merge_info[[3]]
  age <- merge_info[[4]]

  if (age == 14) {
    apply_missing <- mapply(check_missing_s1, wave_data)
  } else if (age == 15) {
    apply_missing <- mapply(check_missing_s2, wave_data)
  } else if (age == 16) {
    apply_missing <- mapply(check_missing_s3, wave_data)
  } else if (age == 17) {
    apply_missing <- mapply(check_missing_s4, wave_data)
  } else if (age == 19) {
    apply_missing <- mapply(check_missing_s6, wave_data)
  } else if (age == 20) {
    apply_missing <- mapply(check_missing_s7, wave_data)
  } else if (age == 25) {
    apply_missing <- mapply(check_missing_s8, wave_data)
  } else if (age == 32) {
    apply_missing <- mapply(check_missing_s9, wave_data)
  }

  any_missing <- any_missing | apply_missing
}

# For those with no drinking observed but at least one missing, assign -8
result$alcfst <- ifelse(result$drinking_observed == FALSE & any_missing, -8, result$alcfst)

# Create factor with correct levels and labels
result$alcfst <- factor(result$alcfst,
                        levels = c(14, 15, 16, 17, 19, 20, 25, 32, 99, -8),
                        labels = c('Age 14', 'Age 15', 'Age 16', 'Age 17', 'Age 19', 'Age 20', 'Age 25', 'Age 32', 'Never had alcohol', "Don't know/insufficient information"))

# Keep only NSID and alcfst
result <- result[, c('NSID', 'alcfst')]

# Write output
write_csv(result, 'data/output/cleaned_data.csv')

